// IspChainFusion.cpp — ISP Extra-op chain fusion for MNN converter.
//
// Reads the exact pattern tables (auto-generated from Rust CPP_FUSION_TABLE)
// and replaces matched op chains with ISP Extra ops.  The pattern tables are
// source-generated by `cam-app --gen-isp-patterns` from
// cam-rust/cam-isp/src/mnn_opset_matcher.rs.
//
// Single-scan strategy (longest-match wins across all tables):
//   - Pass0 table   — concrete const/weight checks (fuse)
//   - Pass1 table   — guard chains (consumed but kept primitive, no Extra)
//   - Profile table — structural-only matching (relaxed const checks)
// All three are scanned at each position; the LONGEST match wins so generic
// 1-op patterns never shadow longer block patterns, and guards protect
// control chains from shorter fusion patterns. Weight producers may be Const
// ops (baked calibration) OR graph Input ops (runtime-fed weights) — fused
// Extras carry every chain input through so the engine can still feed
// per-frame weights.

#include <MNN/MNNDefine.h>
#include <MNN/MNNForwardType.h>
#include <MNN_generated.h>

// Pattern tables — includes ExactPattern.h transitively.
#include "isp_fusion_patterns.h"

#include "../Global.hpp"
#include "../PostTreatUtils.hpp"

#include <algorithm>
#include <cstdint>
#include <functional>
#include <memory>
#include <set>
#include <string>
#include <unordered_map>
#include <vector>

#include "config.hpp"

namespace MNN {

// =====================================================================
// Graph helpers
// =====================================================================

// tensor_index → index of op in oplists that produces it
static std::unordered_map<int, int> buildProducerMap(const NetT* net) {
    std::unordered_map<int, int> producer;
    for (int i = 0; i < static_cast<int>(net->oplists.size()); i++) {
        const auto& op = net->oplists[i];
        if (!op) continue;
        for (int out : op->outputIndexes) {
            producer[out] = i;
        }
    }
    return producer;
}

// Check that op[i]'s output tensor feeds into op[i+1]'s input tensor list.
static bool isConnected(const NetT* net, int srcIdx, int dstIdx) {
    if (srcIdx < 0 || dstIdx < 0) return false;
    if (srcIdx >= static_cast<int>(net->oplists.size())) return false;
    if (dstIdx >= static_cast<int>(net->oplists.size())) return false;
    const auto& src = net->oplists[srcIdx];
    const auto& dst = net->oplists[dstIdx];
    if (!src || !dst) return false;
    for (int out : src->outputIndexes) {
        for (int in : dst->inputIndexes) {
            if (out == in) return true;
        }
    }
    return false;
}

// =====================================================================
// Pattern matching
// =====================================================================

// Verify BinaryOp sub-type matches.
static bool matchBinOp(const OpT* op, int expectedBinOp) {
    if (expectedBinOp < 0) return true;  // any
    if (op->type != OpType_BinaryOp) return false;
    if (op->main.type != OpParameter_BinaryOp) return false;
    const BinaryOpT* bop = op->main.AsBinaryOp();
    if (!bop) return false;
    return static_cast<int>(bop->opType) == expectedBinOp;
}

// Compute the element count of the tensor produced by a Const or Input op.
// Const → blob dims product; Input (runtime-fed weight) → declared input dims.
static int producerTensorElems(const NetT* net, int opIdx) {
    if (opIdx < 0 || opIdx >= static_cast<int>(net->oplists.size())) return -1;
    const auto& op = net->oplists[opIdx];
    if (!op) return -1;
    if (op->type == OpType_Const) {
        if (op->main.type != OpParameter_Blob) return -1;
        const BlobT* blob = op->main.AsBlob();
        if (!blob) return -1;
        int total = 1;
        for (int d : blob->dims) total *= d;
        return total;
    }
    if (op->type == OpType_Input) {
        // Runtime-fed weights are graph Input ops (not baked Consts). Their
        // declared shape carries the element count (e.g. FcsBlock/gain
        // [1,3,1,1] → 3).
        if (op->main.type != OpParameter_Input) return -1;
        const InputT* in = op->main.AsInput();
        if (!in) return -1;
        int total = 1;
        for (int d : in->dims) {
            if (d <= 0) return -1;
            total *= d;
        }
        return total;
    }
    return -1;
}

// Check convolution weight element count.
// Weight tensor is typically the second input (index 1) of a Convolution op.
// The producer may be a Const (baked weight) or an Input op (runtime-fed
// weight) — both carry the element count the pattern checks.
static bool matchConvWeightElems(const OpT* op, int expectedCW,
                                 const std::unordered_map<int, int>& producer,
                                 const NetT* net) {
    if (expectedCW < 0) return true;  // any
    if (op->type != OpType_Convolution && op->type != OpType_ConvolutionDepthwise)
        return true;  // skip check for non-Conv ops
    if (static_cast<int>(op->inputIndexes.size()) < 2) return false;
    int weightTensorIdx = op->inputIndexes[1];
    auto it = producer.find(weightTensorIdx);
    if (it == producer.end()) return false;
    int producerIdx = it->second;
    if (producerIdx < 0) return false;
    const auto& constOp = net->oplists[producerIdx];
    if (!constOp) return false;
    if (constOp->type != OpType_Const && constOp->type != OpType_Input) return false;
    return producerTensorElems(net, producerIdx) == expectedCW;
}

// Check const/input element count at the specified input index.
static bool matchConstElems(const OpT* op, int expectedElems, int constIdx,
                            const std::unordered_map<int, int>& producer,
                            const NetT* net) {
    if (expectedElems < 0) return true;   // any
    if (constIdx < 0) return true;        // not specified
    if (static_cast<int>(op->inputIndexes.size()) <= constIdx) return false;
    int tensorIdx = op->inputIndexes[constIdx];
    auto it = producer.find(tensorIdx);
    if (it == producer.end()) return false;
    int producerIdx = it->second;
    if (producerIdx < 0 || producerIdx >= static_cast<int>(net->oplists.size()))
        return false;
    const auto& constOp = net->oplists[producerIdx];
    if (!constOp) return false;
    if (constOp->type != OpType_Const && constOp->type != OpType_Input) return false;
    return producerTensorElems(net, producerIdx) == expectedElems;
}

// Try to match a chain starting at opIndex against a single pattern.
// Returns the number of ops matched (0 = no match).
// Verifies:
//   1. Op types match in sequence
//   2. Consecutive ops are connected (output → input)
//   3. BinaryOp sub-type matches
//   4. Conv weight element count matches (last op in chain)
//   5. Const element count matches (first op in chain)
static int tryMatch(const NetT* net, int opIndex, const ExactPattern& pat,
                    const std::unordered_map<int, int>& producer) {
    int n = static_cast<int>(pat.opTypes.size());
    if (n <= 0) return 0;
    if (opIndex + n > static_cast<int>(net->oplists.size())) return 0;

    for (int j = 0; j < n; j++) {
        const auto& op = net->oplists[opIndex + j];
        if (!op) return 0;
        if (op->type != pat.opTypes[j]) return 0;

        // Verify connectivity to previous op in chain (skipped for tree-shaped DAGs)
        if (j > 0 && pat.requireConnectivity && !isConnected(net, opIndex + j - 1, opIndex + j)) {
            return 0;
        }
    }

    // Check BinaryOp sub-type on the FIRST BinaryOp in the chain
    if (pat.binOpType != MNN::BinaryOpOperation_ADD) {
        bool found = false;
        for (int j = 0; j < n; j++) {
            if (pat.opTypes[j] == OpType_BinaryOp) {
                if (!matchBinOp(net->oplists[opIndex + j].get(), static_cast<int>(pat.binOpType))) {
                    return 0;
                }
                found = true;
                break;
            }
        }
        // If pattern specifies a binOp but chain has no BinaryOp, reject
        if (!found) return 0;
    }

    // Check conv weight elements on last op (if Conv)
    const auto& lastOp = net->oplists[opIndex + n - 1];
    if (!matchConvWeightElems(lastOp.get(), pat.convWeightElems, producer, net)) {
        return 0;
    }

    // Check const elements on first op
    const auto& firstOp = net->oplists[opIndex];
    if (!matchConstElems(firstOp.get(), pat.constElems, pat.constIndex, producer, net)) {
        return 0;
    }

    return n;
}

// =====================================================================
// Histogram variable-length matching
// =====================================================================

// Match the histogram prefix: ConvertTensor, Convolution, Const, BinaryOp,
// ConvertTensor, Reduction (6 ops). Then walk bin structure.
// Returns total op count if matched, 0 otherwise.
static int matchHistogramPrefix(const NetT* net, int opIndex) {
    static const OpType kPrefix[] = {
        OpType_ConvertTensor, OpType_Convolution, OpType_Const,
        OpType_BinaryOp, OpType_ConvertTensor, OpType_Reduction
    };
    static const int prefixLen = 6;
    int n = static_cast<int>(net->oplists.size());
    if (opIndex + prefixLen > n) return 0;
    for (int j = 0; j < prefixLen; j++) {
        if (!net->oplists[opIndex + j]) return 0;
        if (net->oplists[opIndex + j]->type != kPrefix[j]) return 0;
    }
    int pos = opIndex + prefixLen;
    while (pos < n) {
        // Check for final tail: BinaryOp, ConvertTensor, Reduction, Const, Concat
        if (pos + 5 <= n) {
            bool tail = true;
            static const OpType kTail[] = {
                OpType_BinaryOp, OpType_ConvertTensor, OpType_Reduction,
                OpType_Const, OpType_Concat
            };
            for (int j = 0; j < 5; j++) {
                if (!net->oplists[pos + j] || net->oplists[pos + j]->type != kTail[j]) {
                    tail = false; break;
                }
            }
            if (tail) return pos + 5 - opIndex;
        }
        // Check for inner bin: BinaryOp, Const, BinaryOp, BinaryOp, ConvertTensor, Reduction
        if (pos + 6 <= n) {
            bool bin = true;
            static const OpType kBin[] = {
                OpType_BinaryOp, OpType_Const, OpType_BinaryOp,
                OpType_BinaryOp, OpType_ConvertTensor, OpType_Reduction
            };
            for (int j = 0; j < 6; j++) {
                if (!net->oplists[pos + j] || net->oplists[pos + j]->type != kBin[j]) {
                    bin = false; break;
                }
            }
            if (bin) { pos += 6; continue; }
        }
        break;
    }
    return 0;
}

// =====================================================================
// Chain replacement
// =====================================================================

// Collect the union of all inputs of the matched ops [firstIdx..lastIdx],
// minus internal tensors (outputs of the matched ops). Keeps the frame input
// plus every runtime-fed weight input (Const OR graph Input op) so the fused
// Extra can still be fed per-frame by the engine. Order is first-occurrence.
static std::vector<int> collectChainInputs(const NetT* net, int firstIdx, int lastIdx) {
    std::set<int> internal;
    for (int j = firstIdx; j <= lastIdx; j++) {
        const auto& op = net->oplists[j];
        if (!op) continue;
        for (int out : op->outputIndexes) internal.insert(out);
    }
    std::vector<int> inputs;
    for (int j = firstIdx; j <= lastIdx; j++) {
        const auto& op = net->oplists[j];
        if (!op) continue;
        for (int in : op->inputIndexes) {
            if (internal.count(in)) continue;
            if (std::find(inputs.begin(), inputs.end(), in) == inputs.end()) {
                inputs.push_back(in);
            }
        }
    }
    return inputs;
}

// Create an Extra op that replaces a matched chain.
static std::unique_ptr<OpT> makeExtraOp(const NetT* net, int firstIdx,
                                        int lastIdx,
                                        const ExactPattern& pat) {
    auto extra = std::unique_ptr<OpT>(new OpT());
    extra->type = OpType_Extra;
    extra->name = std::string(pat.ispType);

    // Wire ALL chain inputs through (frame + runtime-fed weight inputs), so
    // the fused op keeps every tensor the engine feeds per-frame. Outputs come
    // from the last op.
    extra->inputIndexes = collectChainInputs(net, firstIdx, lastIdx);
    extra->outputIndexes = net->oplists[lastIdx]->outputIndexes;

    // Create Extra parameter
    auto* extraParam = new ExtraT();
    extraParam->type = std::string(pat.ispType);
    // engine="MNN" so writeFb's unsupported-op validation passes; the
    // VulkanFuse runtime dispatches the custom kernel by `type` (isp.*).
    extraParam->engine = "MNN";
    extraParam->vector = false;
    extra->main.type = OpParameter_Extra;
    extra->main.value = extraParam;

    return extra;
}

// =====================================================================
// Single-scan fusion engine (longest-match wins across all tables)
// =====================================================================

// At opIndex, find the best pattern across all tables: the LONGEST match wins
// (so a 2-op `{BinaryOp, ReLU6}` block pattern beats a 1-op generic `{BinaryOp}`
// pattern at the same position), ties go to the earlier table (Pass0 concrete
// fusions before Pass1 guards before Profile structural), preserving the
// original precedence for equal-length candidates.
struct BestMatch {
    const ExactPattern* pat = nullptr;
    int len = 0;
    int order = 0;  // table index; lower = higher precedence
    bool found = false;
};

static BestMatch bestMatchAt(const NetT* net, int opIndex,
                             const ExactPattern* const tables[],
                             const int tableSizes[], int nTables,
                             const std::unordered_map<int, int>& producer) {
    BestMatch best;
    for (int t = 0; t < nTables; t++) {
        for (int p = 0; p < tableSizes[t]; p++) {
            const auto& pat = tables[t][p];
            int matched = tryMatch(net, opIndex, pat, producer);
            if (matched <= 0) continue;
            if (!best.found || matched > best.len ||
                (matched == best.len && t < best.order)) {
                best.pat = &pat;
                best.len = matched;
                best.order = t;
                best.found = true;
            }
        }
    }
    return best;
}

// Run one scan over the whole net: histogram first, then best pattern.
// Returns number of ops consumed (fused or guarded).
static int runFusion(NetT* net, const ExactPattern* const tables[],
                     const int tableSizes[], int nTables) {
    int consumed = 0;
    std::set<int> seen;  // op indices already consumed
    auto producer = buildProducerMap(net);

    for (int i = 0; i < static_cast<int>(net->oplists.size()); i++) {
        if (seen.count(i)) continue;
        if (!net->oplists[i]) continue;

        // Try variable-length histogram match first
        int histLen = matchHistogramPrefix(net, i);
        if (histLen > 0) {
            for (int j = 0; j < histLen; j++) {
                seen.insert(i + j);
            }
            // Replace chain with Extra op
            auto extra = std::unique_ptr<OpT>(new OpT());
            extra->type = OpType_Extra;
            extra->name = "isp.histogram";
            extra->inputIndexes = collectChainInputs(net, i, i + histLen - 1);
            extra->outputIndexes = net->oplists[i + histLen - 1]->outputIndexes;
            auto* extraParam = new ExtraT();
            extraParam->type = "isp.histogram";
            extraParam->engine = "MNN";
            extraParam->vector = false;
            extra->main.type = OpParameter_Extra;
            extra->main.value = extraParam;
            for (int j = 1; j < histLen; j++) {
                net->oplists[i + j].reset();
            }
            net->oplists[i] = std::move(extra);
            producer = buildProducerMap(net);
            consumed += histLen;
            continue;
        }

        BestMatch best = bestMatchAt(net, i, tables, tableSizes, nTables, producer);
        if (!best.found) continue;

        // Mark all matched ops as seen
        for (int j = 0; j < best.len; j++) {
            seen.insert(i + j);
        }

        if (!best.pat->noFuse) {
            // Replace chain with Extra op
            auto extraOp = makeExtraOp(net, i, i + best.len - 1, *best.pat);

            // Null out consumed ops (except first, which we replace)
            for (int j = 1; j < best.len; j++) {
                net->oplists[i + j].reset();
            }
            // Place the Extra op at the first position
            net->oplists[i] = std::move(extraOp);
            // Rebuild producers after the mutation so later matches see the
            // fused op as the producer of its outputs.
            producer = buildProducerMap(net);
        }
        // else: guard chain — consumed but kept primitive

        consumed += best.len;
    }
    return consumed;
}

// =====================================================================
// Public entry point — called from optimizeNet() in the postconvert
// pipeline.  Runs the single longest-match scan when input is MNN and
// output is MNN.
// =====================================================================

int optimizeIspChain(NetT* net, const modelConfig& config) {
    if (!net) return 0;

    // ISP fusion applies when input is already MNN (MNN→MNN re-optimization).
    // Output is always MNN; only run when input source is also MNN.
    if (config.model != modelConfig::MNN) return 0;

    // Merged tables cover the three input conventions (PackedInt32,
    // PureInt16, RawInt32); longest-match-wins resolves cross-table
    // shadowing: generic 1-op patterns never steal from longer block
    // patterns, and noFuse guards protect control chains from shorter
    // fusion patterns.
    const ExactPattern* tables[] = {
        kExactFusionTablesPass0,
        kExactFusionTablesPass1,
        kExactProfileVariants,
    };
    const int tableSizes[] = {
        (int)(sizeof(kExactFusionTablesPass0) / sizeof(ExactPattern)),
        (int)(sizeof(kExactFusionTablesPass1) / sizeof(ExactPattern)),
        (int)(sizeof(kExactProfileVariants) / sizeof(ExactPattern)),
    };
    const int nTables = 3;

    int totalFused = runFusion(net, tables, tableSizes, nTables);

    // Compact nulled (consumed) ops: runFusion nulls fused chains in place,
    // and downstream converter passes (e.g. TransformBatchNormal) dereference
    // every oplists entry — null entries would crash them.
    net->oplists.erase(std::remove_if(net->oplists.begin(), net->oplists.end(),
                                      [](const std::unique_ptr<OpT>& o) { return !o; }),
                       net->oplists.end());

    return totalFused;
}

// ── Registration ──
// Re-registers the rewrite (free function optimizeIspChain) as the
// "IspChainFusion" PostConverter pass so the optimizer pipeline finds it.
// The pass only fuses for MNN→MNN input (see optimizeIspChain).
class IspChainFusionPass : public PostConverter {
public:
    bool onExecute(std::unique_ptr<MNN::NetT>& net) const override {
        auto config = Global<modelConfig>::Get();
        if (config == nullptr) {
            return false;
        }
        optimizeIspChain(net.get(), *config);
        return true;
    }
};
static PostConverterRegister<IspChainFusionPass> __isp_fusion_pass("IspChainFusion");

// ── Post-format-converter cleanup ──
// Removes ConvertTensor ops inserted by AddTensorFormatConverter between
// Extra (isp.*) ops — these break the VulkanFuse Extra chain because the
// conversion inserts an NC4HW4↔NCHW layout change the custom SPIR-V doesn't
// handle. Runs AFTER AddTensorFormatConverter in the converter pipeline.
class RemoveExtraConvertTensor : public PostConverter {
public:
    bool onExecute(std::unique_ptr<MNN::NetT>& net) const override {
        auto& ops = net->oplists;
        bool changed = false;
        bool any = true;
        while (any) {
            any = false;
            for (int i = 0; i < (int)ops.size(); i++) {
                if (!ops[i] || ops[i]->type != MNN::OpType_ConvertTensor) continue;
                auto& ct = ops[i];
                if (ct->inputIndexes.size() != 1 || ct->outputIndexes.size() != 1) continue;
                int ctIn = ct->inputIndexes[0];
                int ctOut = ct->outputIndexes[0];

                // Check if ctIn comes from an Extra op
                bool fromExtra = false;
                for (auto& op : ops) {
                    if (!op || op->type != MNN::OpType_Extra) continue;
                    for (auto outIdx : op->outputIndexes) {
                        if (outIdx == ctIn) { fromExtra = true; break; }
                    }
                    if (fromExtra) break;
                }
                if (!fromExtra) continue;

                // Check if ctOut is consumed by an Extra op
                for (auto& op : ops) {
                    if (!op || op.get() == ct.get() || op->type != MNN::OpType_Extra) continue;
                    bool rerouted = false;
                    for (auto& inIdx : op->inputIndexes) {
                        if (inIdx == ctOut) {
                            inIdx = ctIn;  // reroute to ConvertTensor input
                            rerouted = true;
                        }
                    }
                    if (rerouted) {
                        ct.reset();
                        changed = true;
                        any = true;
                        break;
                    }
                }
                if (any) break;  // restart scan
            }
        }
        if (changed) {
            ops.erase(std::remove_if(ops.begin(), ops.end(),
                [](const std::unique_ptr<OpT>& o) { return !o; }), ops.end());
        }
        return changed;
    }
};
static PostConverterRegister<RemoveExtraConvertTensor> __rm_extra_convert("RemoveExtraConvertTensor");

} // namespace MNN
